import os

def find_files(directory):
    try:
        files = []
        for entry in os.listdir(directory):
            full_path = os.path.join(directory, entry)
            if os.path.isfile(full_path):
                files.append(entry)
        return files
    except (OSError, IOError) as e:
        raise e
